From eeea506c41486aa40e2d1300ab516b99edc7e489 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:35:28 +0100
Subject: [PATCH] configview: remember whether the settings window was
 maximized

The size was saved on every resize, so a window closed while maximized
came back as a normal window as big as the screen. Save the size and the
maximized state when the window closes and open it maximized again.

BUG: 511082
---
 src/plasmaquick/configview.cpp | 40 ++++++++++++++++++++++++++++------
 1 file changed, 33 insertions(+), 7 deletions(-)

diff --git a/src/plasmaquick/configview.cpp b/src/plasmaquick/configview.cpp
index 87dd9da24..22ff109f2 100644
--- a/src/plasmaquick/configview.cpp
+++ b/src/plasmaquick/configview.cpp
@@ -249,6 +249,28 @@ ConfigView::ConfigView(Plasma::Applet *applet, QWindow *parent)
     setIcon(QIcon::fromTheme(QStringLiteral("configure")));
     d->init();
     connect(applet, &QObject::destroyed, this, &ConfigView::close);
+    connect(this, &QWindow::visibleChanged, this, [this](bool visible) {
+        if (!visible || !d->applet) {
+            return;
+        }
+        KConfigGroup cg = d->applet.data()->config();
+        cg = KConfigGroup(&cg, QStringLiteral("ConfigDialog"));
+        if (cg.readEntry("DialogMaximized", false)) {
+            const QSize normalSize = size();
+            setWindowState(Qt::WindowMaximized);
+            // The window was never shown at its normal size, so restore it ourselves
+            connect(
+                this,
+                &QWindow::windowStateChanged,
+                this,
+                [this, normalSize](Qt::WindowState state) {
+                    if (state == Qt::WindowNoState) {
+                        resize(normalSize);
+                    }
+                },
+                Qt::SingleShotConnection);
+        }
+    });
 }

 ConfigView::~ConfigView()
@@ -342,6 +364,17 @@ void ConfigView::setAppletGlobalShortcut(const QString &shortcut)
 // To emulate Qt::WA_DeleteOnClose that QWindow doesn't have
 void ConfigView::hideEvent(QHideEvent *ev)
 {
+    if (d->applet) {
+        KConfigGroup cg = d->applet.data()->config();
+        cg = KConfigGroup(&cg, QStringLiteral("ConfigDialog"));
+        const bool maximized = windowState() == Qt::WindowMaximized;
+        cg.writeEntry("DialogMaximized", maximized);
+        if (!maximized) {
+            cg.writeEntry("DialogWidth", width());
+            cg.writeEntry("DialogHeight", height());
+        }
+    }
+
     QQuickWindow::hideEvent(ev);
     deleteLater();
 }
@@ -354,13 +387,6 @@ void ConfigView::resizeEvent(QResizeEvent *re)

     d->rootItem->setSize(re->size());

-    if (d->applet) {
-        KConfigGroup cg = d->applet.data()->config();
-        cg = KConfigGroup(&cg, QStringLiteral("ConfigDialog"));
-        cg.writeEntry("DialogWidth", re->size().width());
-        cg.writeEntry("DialogHeight", re->size().height());
-    }
-
     QQuickWindow::resizeEvent(re);
 }

